/** Which keep picture to show for a rank (stage index 0-6). */
export function keepSpriteForStage(stage: number): string {
  if (stage <= 1) return 'keep0';
  if (stage <= 3) return 'keep1';
  if (stage <= 5) return 'keep2';
  return 'keep3';
}
